script:
// Custom HTML Block - QR Code Generator (JavaScript)
// Paste this in a <script> tag

// ⚙️ CONFIGURATION - Change these values
const QR_LINK = "https://lms.emporiumsolutions.com/admission-form/new";
const FORM_TYPE = "inquiry"; // "inquiry" or "admission"
const LOGO_PATH = "/assets/job_club/images/logo-es.png";

// Load QRCode.js library if not already loaded
if (!window.QRCode) {
    const script = document.createElement("script");
    script.src = "https://cdn.jsdelivr.net/npm/qrcodejs@1.0.0/qrcode.min.js";
    script.onload = () => initializeQRCode();
    document.head.appendChild(script);
} else {
    initializeQRCode();
}

function initializeQRCode() {
    // Get elements
    const qrDisplay = root_element.querySelector('#qr-code-display');
    const qrLabel = root_element.querySelector('#qr-label');
    const qrLinkDisplay = root_element.querySelector('#qr-link-display');
    const downloadBtn = root_element.querySelector('#btn-download');
    const copyBtn = root_element.querySelector('#btn-copy');

    // Check if required elements exist
    if (!qrDisplay || !qrLabel || !downloadBtn || !copyBtn) {
        console.error('Required QR elements not found');
        return;
    }

    // Generate QR Code
    const qrCode = new QRCode(qrDisplay, {
        text: QR_LINK,
        width: 200,
        height: 200,
        colorDark: '#000000',
        colorLight: '#ffffff',
        correctLevel: QRCode.CorrectLevel.H
    });

    // Set labels
    const formLabel = FORM_TYPE === 'inquiry' ? 'Inquiry Form' : 'Student Admission Form';
    qrLabel.textContent = formLabel;
    
    // Only set link display if element exists
    if (qrLinkDisplay) {
        qrLinkDisplay.textContent = QR_LINK;
    }

    // Download button handler
    downloadBtn.onclick = function() {
        const qrImg = qrDisplay.querySelector('img') || qrDisplay.querySelector('canvas');
        
        if (!qrImg) {
            showAlert('QR code not found', 'red');
            return;
        }

        const logo = new Image();
        logo.crossOrigin = 'anonymous';
        logo.src = LOGO_PATH;

        logo.onload = function() {
            createQRWithLogo(qrImg, logo, formLabel);
        };

        logo.onerror = function() {
            downloadSimpleQR(qrImg);
        };
    };

    // Copy button handler
    copyBtn.onclick = function() {
        navigator.clipboard.writeText(QR_LINK)
            .then(() => showAlert('Link copied to clipboard!', 'green'))
            .catch(() => showAlert('Failed to copy link', 'red'));
    };
}

function createQRWithLogo(qrImg, logo, formLabel) {
    const qrSize = 200;
    const padding = 20;
    const logoHeight = 50;
    const textHeight = 30;

    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');

    canvas.width = qrSize + padding * 2;
    canvas.height = logoHeight + qrSize + textHeight + padding * 3;

    // White background
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Draw logo on top
    const logoX = (canvas.width - 100) / 2;
    ctx.drawImage(logo, logoX, padding, 100, logoHeight);

    // Draw QR code
    const qrImage = new Image();
    qrImage.crossOrigin = 'anonymous';
    qrImage.src = qrImg.src || qrImg.toDataURL('image/png');

    qrImage.onload = function() {
        const qrX = padding;
        const qrY = padding * 2 + logoHeight;
        ctx.drawImage(qrImage, qrX, qrY, qrSize, qrSize);

        // Add text below QR
        ctx.font = 'bold 16px Arial';
        ctx.fillStyle = '#000000';
        ctx.textAlign = 'center';
        ctx.fillText(formLabel, canvas.width / 2, qrY + qrSize + 25);

        // Download
        const link = document.createElement('a');
        link.download = FORM_TYPE === 'inquiry' ? 'inquiry_form_qr.png' : 'student_admission_qr.png';
        link.href = canvas.toDataURL('image/png');
        link.click();

        showAlert('QR Code downloaded successfully!', 'green');
    };
}

function downloadSimpleQR(qrImg) {
    const link = document.createElement('a');
    link.download = FORM_TYPE === 'inquiry' ? 'inquiry_form_qr.png' : 'student_admission_qr.png';
    link.href = qrImg.src || qrImg.toDataURL('image/png');
    link.click();
    
    showAlert('QR Code downloaded!', 'green');
}

function showAlert(message, color) {
    if (typeof frappe !== 'undefined' && frappe.show_alert) {
        frappe.show_alert({
            message: message,
            indicator: color
        });
    } else {
        alert(message);
    }
}

