script:
// Add smooth scroll animation on page load
document.addEventListener('DOMContentLoaded', function() {
  const cards = document.querySelectorAll('.attendance-card');
  
  cards.forEach((card, index) => {
    // Add staggered entrance animation
    card.style.opacity = '0';
    card.style.transform = 'translateY(20px)';
    
    setTimeout(() => {
      card.style.transition = 'opacity 0.6s ease, transform 0.6s ease';
      card.style.opacity = '1';
      card.style.transform = 'translateY(0)';
    }, index * 150);
  });

  // Add click tracking (optional)
  const buttons = document.querySelectorAll('.card-button');
  buttons.forEach(button => {
    button.addEventListener('click', function(e) {
      const cardTitle = this.closest('.attendance-card').querySelector('.card-title').textContent;
      console.log(`Navigating to: ${cardTitle}`);
      // You can add analytics tracking here if needed
    });
  });

  // Add ripple effect on button click
  buttons.forEach(button => {
    button.addEventListener('mousedown', function(e) {
      const ripple = document.createElement('span');
      const rect = this.getBoundingClientRect();
      const size = Math.max(rect.width, rect.height);
      const x = e.clientX - rect.left - size / 2;
      const y = e.clientY - rect.top - size / 2;
      
      ripple.style.width = ripple.style.height = size + 'px';
      ripple.style.left = x + 'px';
      ripple.style.top = y + 'px';
      ripple.classList.add('ripple-effect');
      
      this.appendChild(ripple);
      
      setTimeout(() => ripple.remove(), 600);
    });
  });
});

// Optional: Add CSS for ripple effect dynamically
const style = document.createElement('style');
style.textContent = `
  .card-button {
    position: relative;
    overflow: hidden;
  }
  
  .ripple-effect {
    position: absolute;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.6);
    transform: scale(0);
    animation: ripple-animation 0.6s ease-out;
    pointer-events: none;
  }
  
  @keyframes ripple-animation {
    to {
      transform: scale(4);
      opacity: 0;
    }
  }
`;
document.head.appendChild(style);

